import sys

def longest_subarray_with_each_element_twice(arr):
    n = len(arr)
    if n < 2:
        return 0

    arr.sort()
    max_length = 0
    current_length = 0
    count = 1

    for i in range(1, n):
        if arr[i] == arr[i - 1]:
            count += 1
        else:
            if count == 2:
                current_length += 2
            elif count > 2:
                current_length = 2
            else:
                current_length = 0
            count = 1

        if current_length > max_length:
            max_length = current_length

    # Check the last segment
    if count == 2:
        current_length += 2
    elif count > 2:
        current_length = 2

    if current_length > max_length:
        max_length = current_length

    return max_length

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    arr = list(map(int, data[1:]))

    result = longest_subarray_with_each_element_twice(arr)
    print(result)

if __name__ == "__main__":
    main()
